/**
 * Reads `Metadata/Slic3r_PE.config`, where PrusaSlicer and the slicers built
 * on it keep a project's print, filament and printer settings: one key per
 * line in G-code-comment form, `; key = value`, after a first line naming
 * the slicer (`; generated by PrusaSlicer 2.9.6 on 2026-10-31 at 07:34:25 UTC`).
 *
 * Values are kept as strings, unescaped the way PrusaSlicer's own reader
 * does it: every value may hold C-style escapes (`\n` in a G-code block,
 * `\"` and `\\`), and a value that needed it was written in double quotes.
 * A list of numbers (one per extruder) is joined with commas; a list of
 * strings (preset names, colors) with semicolons, each element quoted when it
 * needs to be. The key map knows which keys are lists of which kind.
 *
 * The file is untrusted: lines are capped, a repeated key keeps its last
 * value (as PrusaSlicer does), and anything that isn't `; key = value` is
 * ignored rather than refused.
 */

export interface PrusaIni {
  /** The slicer named on the first line, e.g. "PrusaSlicer", or null when the line doesn't say. */
  slicer: string | null;
  /** Its version as written, e.g. "2.9.6" or "2.7.0+win64", or null. */
  version: string | null;
  /** Every `; key = value` line, unescaped, last value wins. */
  settings: Map<string, string>;
  /** The same values as written, for `splitStringList`. */
  raw: Map<string, string>;
}

/** The most lines read; a real config has a few hundred. */
const MAX_LINES = 5000;
/** A key is a plain identifier; anything else isn't a setting line. */
const KEY = /^[a-z][a-z0-9_]{0,99}$/;
const GENERATED_BY = /^; generated by ([A-Za-z][A-Za-z0-9]{1,30}(?: [A-Za-z][A-Za-z0-9]{1,30})?) v?(\d[\w.+-]{0,40})/;

export function parsePrusaIni(text: string): PrusaIni {
  const settings = new Map<string, string>();
  const raw = new Map<string, string>();
  let slicer: string | null = null;
  let version: string | null = null;
  const lines = text.split(/\r?\n/, MAX_LINES);
  const first = GENERATED_BY.exec(lines[0] ?? "");
  if (first) {
    slicer = first[1];
    version = first[2];
  }
  for (const line of lines) {
    if (!line.startsWith("; ")) continue;
    const eq = line.indexOf(" = ");
    if (eq < 0) continue;
    const key = line.slice(2, eq);
    if (!KEY.test(key)) continue;
    raw.set(key, line.slice(eq + 3));
    settings.set(key, unescapeValue(line.slice(eq + 3)));
  }
  return { slicer, version, settings, raw };
}

/**
 * One value as PrusaSlicer wrote it: C-style escapes undone (`\n`, `\r`, `\"`, `\\`), and surrounding double
 * quotes, if any, removed.
 */
export function unescapeValue(value: string): string {
  const inner = value.length >= 2 && value.startsWith('"') && value.endsWith('"') ? value.slice(1, -1) : value;
  let out = "";
  for (let i = 0; i < inner.length; i++) {
    const c = inner[i];
    if (c !== "\\" || i === inner.length - 1) {
      out += c;
      continue;
    }
    const next = inner[++i];
    out += next === "n" ? "\n" : next === "r" ? "\r" : next;
  }
  return out;
}

/** A list of numbers, one per extruder: PrusaSlicer joins them with commas. */
export function splitNumberList(value: string): string[] {
  return value.split(",");
}

/**
 * A list of strings, one per extruder (preset names, colors, G-code blocks): PrusaSlicer joins them with
 * semicolons and quotes any element that holds a semicolon, a quote, a backslash or a newline. The raw value
 * must be split before unescaping, so pass the line's value, not `settings.get()`'s unescaped one.
 */
export function splitStringList(raw: string): string[] {
  const out: string[] = [];
  let current = "";
  let quoted = false;
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    if (quoted) {
      if (c === "\\" && i < raw.length - 1) {
        current += c + raw[++i];
      } else if (c === '"') {
        quoted = false;
        current += c;
      } else current += c;
    } else if (c === '"') {
      quoted = true;
      current += c;
    } else if (c === ";") {
      out.push(current);
      current = "";
    } else current += c;
  }
  out.push(current);
  return out.map(unescapeValue);
}
